// Öğretim için özgün, hareketli HTML şemaları. Hareket CSS'te azaltılabilir.
const captions={
 flow:'Bir ekranın ardındaki dört sınır: kullanıcı, istemci, servis ve veri kaynağı. İstek ileri, yanıt geri gider.',
 network:'Bir isteğin ilk yolculuğu: ad çözümleme, bağlantı, TLS anlaşması ve HTTP. Önbellek ve bağlantı yeniden kullanımı adımları kısaltabilir.',
 http:'İstek yöntemi, yol, başlık ve gövde taşır; yanıt durum kodu, başlık ve gövdeyle geri döner.',
 contract:'API sözleşmesi istemci ve servis arasında veri, yetki, hata ve değişiklik davranışını tanımlar.',
 operations:'Entegrasyonun üç sınırı: sayfalama, hız limiti ve olay teslimi. Her biri ayrı kullanıcı durumu üretir.'
};
const visuals={
 flow:`<div class="flow-stages"><div class="flow-stage"><span class="stage-index">01</span><span class="stage-symbol">↗</span><strong>Kullanıcı</strong><small>Eylemi başlatır</small></div><div class="flow-stage"><span class="stage-index">02</span><span class="stage-symbol">▣</span><strong>İstemci</strong><small>İsteği kurar</small></div><div class="flow-stage"><span class="stage-index">03</span><span class="stage-symbol">◇</span><strong>Servis</strong><small>Kuralı uygular</small></div><div class="flow-stage"><span class="stage-index">04</span><span class="stage-symbol">▤</span><strong>Veri</strong><small>Kaydı sağlar</small></div></div><div class="flow-track"><span class="flow-packet" aria-hidden="true"></span></div><div class="diagram-foot"><span>İstek →</span><span>← Yanıt · hata · belirsizlik</span></div>`,
 network:`<div class="network-track"><div class="network-phase"><span>01</span><strong>DNS</strong><small>Ad → adres</small></div><div class="network-phase"><span>02</span><strong>Bağlantı</strong><small>Yol kurulur</small></div><div class="network-phase"><span>03</span><strong>TLS</strong><small>Kimlik + koruma</small></div><div class="network-phase"><span>04</span><strong>HTTP</strong><small>İstek / yanıt</small></div></div><div class="network-meter"><i></i></div><div class="diagram-foot"><span>İlk ziyaret: adımlar görünür</span><span>Tekrar: önbellek / yeniden kullanım</span></div>`,
 http:`<div class="http-panels"><div class="http-panel"><span class="panel-label">İSTEK / CLIENT →</span><code>POST /sessions</code><div class="code-row"><span>Header</span><b>Content-Type: application/json</b></div><div class="code-row"><span>Body</span><b>{ email, password }</b></div></div><div class="http-flow" aria-hidden="true"><span>→</span><span>←</span></div><div class="http-panel"><span class="panel-label">← SERVER / YANIT</span><code>401 Unauthorized</code><div class="code-row"><span>Header</span><b>Content-Type: application/json</b></div><div class="code-row"><span>Body</span><b>{ code: INVALID_CREDENTIALS }</b></div></div></div><div class="diagram-foot"><span>Protokol sonucu ≠ kullanıcı amacının sonucu</span></div>`,
 contract:`<div class="contract-top"><div class="contract-actor"><span class="actor-symbol">▣</span><strong>Mobil istemci</strong><small>Eski ve yeni sürümler</small></div><div class="contract-sheet"><span class="panel-label">SÖZLEŞME / GET /campaigns</span><div class="contract-lines"><span>Girdi · limit / cursor</span><span>Yetki · kapsam</span><span>Yanıt · items / nextCursor</span><span>Hata · 401 / 429</span></div></div><div class="contract-actor"><span class="actor-symbol">◇</span><strong>Servis</strong><small>İş kuralı ve veri</small></div></div><div class="diagram-foot"><span>Değişiklik → tüketicinin davranışını etkiler</span></div>`,
 operations:`<div class="ops-grid"><div class="ops-card"><span class="panel-label">01 / SAYFALAMA</span><strong>20 kayıt <em>→</em> 20 kayıt</strong><div class="mini-pages"><i></i><i></i><i></i></div><small>Cursor sıralamada konum tutar</small></div><div class="ops-card"><span class="panel-label">02 / HIZ SINIRI</span><strong>429 <em>→</em> bekle</strong><div class="mini-rate"><i></i></div><small>Retry-After ve deneme bütçesi</small></div><div class="ops-card"><span class="panel-label">03 / OLAY TESLİMİ</span><strong>Webhook <em>→</em> durum</strong><div class="mini-events"><i></i><i></i><i></i></div><small>Tekrar ve sıra değişimi olabilir</small></div></div><div class="diagram-foot"><span>Her teknik sınırın görünür ürün karşılığı vardır</span></div>`
};
export function diagram(type){return `<figure class="concept-figure" role="group" aria-label="${captions[type]}"><figcaption><span class="figure-kicker">SİSTEM ŞEMASI</span><span>${captions[type]}</span></figcaption>${visuals[type]}</figure>`}
